import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Module 10 · Rent escrow","description":"","frontmatter":{},"headers":[],"relativePath":"modules/10-rent-escrow.md","filePath":"modules/10-rent-escrow.md","lastUpdated":1790431304000}'),i={name:"modules/10-rent-escrow.md"};function o(r,e,d,l,h,c){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="module-10-·-rent-escrow" tabindex="-1">Module 10 · Rent escrow <a class="header-anchor" href="#module-10-·-rent-escrow" aria-label="Permalink to &quot;Module 10 · Rent escrow&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>RentEscrow.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Housing</td></tr><tr><td><strong>Standard</strong></td><td>None — a state machine over ERC-20 and ERC-721</td></tr><tr><td><strong>Stamp</strong></td><td>Module 10 (awarded to the <strong>tenant</strong> on acceptance)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>A tenancy deposit is money the tenant owns, held by the landlord, returnable at the end if nothing is damaged. The landlord decides whether anything is damaged.</p><p>That is an obvious conflict of interest, and the numbers show it: deposit disputes are among the most common consumer complaints in any country with a rental market. Several countries responded with statutory deposit protection schemes — a third party holds the money, precisely because the landlord should not.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>The contract is the protection scheme. It holds the deposit from the moment the tenant accepts the lease, and neither party can touch it.</p><p>The end-of-tenancy rules are where the design lives:</p><ul><li>The landlord may claim some or all of the deposit, <strong>in public, with a stated reason</strong>, within a fixed window after the lease ends.</li><li>If they do not claim within that window, the tenant simply takes the money back. Nobody has to agree, and the landlord cannot stall.</li><li>If they do claim, it becomes a dispute and a human arbiter splits it.</li></ul><p>Note the default: <strong>silence returns the money to the tenant.</strong> In most real disputes, the default runs the other way, and that asymmetry is most of the problem.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Deposit.</strong> Money held as security against damage or unpaid rent. It remains the tenant&#39;s property throughout; holding is not owning.</p><p><strong>Claim window.</strong> A bounded period after the lease ends during which the landlord may make a claim. Bounded in both directions: <code>MIN_CLAIM_WINDOW</code> two minutes, <code>MAX_CLAIM_WINDOW</code> thirty days.</p><p><strong>State machine, again.</strong> <code>None → Offered → Active → Settled</code>, with a detour through <code>Claimed</code>. Module 5 introduced the pattern; here it carries two assets and a second contract.</p><p><strong>Composition.</strong> This contract reads <code>PropertyDeeds</code> (module 9) to check who may offer a lease. Modules that build on each other, through interfaces rather than inheritance, is how real systems are assembled.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Offered ──accept──▸ Active ──(window passes, tenant acts)──▸ Settled</span></span>
<span class="line"><span>                      │</span></span>
<span class="line"><span>                      └──landlord claims──▸ Claimed ──arbiter──▸ Settled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>When</th></tr></thead><tbody><tr><td><code>offerLease(deedId, tenant, rent, deposit, term, claimWindow)</code></td><td>the deed owner</td><td>Creates the offer</td></tr><tr><td><code>acceptLease(id)</code></td><td>the named tenant</td><td>Pays the deposit in</td></tr><tr><td><code>payRent(id)</code></td><td>the tenant</td><td>While active, before the end</td></tr><tr><td><code>claimDeposit(id, amount, reason)</code></td><td>the landlord</td><td>After the end, inside the window</td></tr><tr><td><code>returnDeposit(id)</code></td><td>the tenant</td><td>After the window, if no claim</td></tr><tr><td><code>resolveClaim(id, toLandlord)</code></td><td><code>ARBITER_ROLE</code></td><td>Only from <code>Claimed</code></td></tr></tbody></table><p>Bounds: <code>MIN_TERM</code> five minutes, <code>MAX_TERM</code> 365 days.</p><p><strong>Rent is not escrowed.</strong> <code>payRent</code> transfers straight from tenant to landlord:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (l.rent </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) token.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeTransferFrom</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, l.landlord, l.rent);</span></span></code></pre></div><p>Only the deposit is held. This is deliberate and correct — rent is payment for a service already received, and escrowing it would give the tenant an unearned lever. Being clear about <em>which</em> money is in dispute is half of designing an escrow.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Ownership of the deed is checked at offer time, and only then:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">address</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owner </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> deeds.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ownerOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(deedId);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owner) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> NotTheDeedOwner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(owner);</span></span></code></pre></div><p>After that, the lease stands on its own. Sell the house mid-tenancy and the lease does not follow — the old landlord still receives rent and still controls the deposit claim.</p><p>That is a bug if you think of this as a property system, and a <em>lesson</em> if you think of it as a teaching contract: <strong>a snapshot check is not an ongoing relationship.</strong> Real leases bind successors in title; that is a legal concept with no on-chain equivalent unless you build one. Fixing it is the first extension, and there is no clean fix — you must choose between reading <code>ownerOf</code> on every call (the landlord changes underneath the tenant) and freezing the landlord at offer time (what the contract does). Both are defensible; neither is what the law does.</p><p><strong>The claim must carry a reason</strong>, stored and emitted:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l.claimReason </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> reason;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">emit</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DepositClaimed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(id, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">msg.sender</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, amount, reason);</span></span></code></pre></div><p>The contract cannot judge the reason. What it can do is make the reason permanent, public, and attributable — so a landlord who claims &quot;cleaning&quot; on every tenancy leaves a visible pattern. That is a weaker mechanism than adjudication, and a real one: much of what regulation achieves is simply making behaviour legible.</p><p><strong>The tenant&#39;s exit needs nobody&#39;s cooperation.</strong> <code>returnDeposit</code> requires only that the window has closed. No landlord signature, no arbiter, no admin. Every escrow should be examined for the question &quot;what if the counterparty simply stops responding?&quot;, and this is the answer to it.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Register a property in module 9, so you hold a deed.</li><li>Offer a lease to a classmate with a short term and a short claim window.</li><li><strong>Tenant:</strong> accept. The deposit leaves your wallet — check the contract&#39;s balance.</li><li><strong>Tenant:</strong> pay rent a couple of times. It goes straight to the landlord, not the contract.</li><li>Wait for the term to end, then the claim window. <strong>Tenant:</strong> <code>returnDeposit</code>.</li></ol><p>Then the disputed path:</p><ol start="6"><li>A second lease. When it ends, the landlord claims part of the deposit with a reason.</li><li>The tenant cannot take it back now — <code>WrongState(Claimed)</code>.</li><li>The instructor resolves the split. Both sides are paid in the same transaction.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LeaseOffered(id: 2, landlord: 0x…, tenant: 0x…, rent: 5e18, deposit: 20e18, endsAt: 1790…)</span></span>
<span class="line"><span>LeaseAccepted(id: 2, tenant: 0x…, deposit: 20e18)</span></span>
<span class="line"><span>Stamped(tokenId: …, moduleId: 10, by: rentEscrow)</span></span>
<span class="line"><span>RentPaid(id: 2, tenant: 0x…, amount: 5e18, paymentNumber: 1)</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span>DepositClaimed(id: 2, landlord: 0x…, amount: 8e18, reason: &quot;carpet&quot;)</span></span>
<span class="line"><span>ClaimResolved(id: 2, arbiter: 0x…, toLandlord: 3e18, toTenant: 17e18)</span></span></code></pre></div><p><code>rentPaid</code> is a counter, not a schedule. The contract does not know whether rent is monthly or weekly, or whether a payment is late — it counts. Ask yourself what it would take to enforce a schedule, and whether you would want a contract that can declare you in arrears.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For residential tenancy, the statutory schemes are better: they have adjudicators who look at photographs, they are free to the tenant, they are backed by law, and they can be appealed.</p><p>Escrow on a chain becomes interesting for <strong>short lets between strangers with no shared platform</strong>, for <strong>equipment or venue hire</strong> where the sums are small and a platform&#39;s cut is not, and as a <strong>transparency layer</strong> — even a scheme that keeps human adjudication can benefit from claims being publicly logged rather than buried in a ticketing system.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Whether the carpet was actually stained.</strong> No photograph is on chain, and a hash of one proves only that it existed.</li><li><strong>The arbiter.</strong> One human, one role, the same honest limitation as module 5.</li><li><strong>Landlord changes.</strong> As above.</li><li><strong>Rent arrears.</strong> The contract counts payments; it has no view on whether they were due.</li><li><strong>Eviction, repairs, habitability</strong> — everything that makes tenancy law long.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Escrowing the rent as well as the deposit.</strong> Gives the tenant a hostage.</li><li><strong>Letting the landlord claim with no deadline.</strong> The deposit never comes back.</li><li><strong>Requiring the landlord to agree to the return.</strong> Reintroduces exactly the problem the contract exists to solve.</li><li><strong>Allowing a claim larger than the deposit.</strong> <code>ClaimTooLarge</code> exists for a reason; without it, <code>deposit - toLandlord</code> underflows or the split is nonsense.</li><li><strong>Forgetting that the tenant must <code>approve</code> the token first.</strong> Two transactions, and the first failure students hit.</li><li><strong>Reading <code>ownerOf</code> inside a pranked call in tests.</strong> See the note in the repository&#39;s test files; this has bitten us more than once.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can the landlord claim after the window? Can the tenant withdraw during it?</li><li>[ ] Can <code>resolveClaim</code> send funds anywhere other than the two parties?</li><li>[ ] Does <code>toLandlord + toTenant</code> always equal the deposit exactly?</li><li>[ ] Can a lease be accepted twice, or by someone other than the named tenant?</li><li>[ ] Can rent be paid after the lease ends? Should it be?</li><li>[ ] What happens if the deed is transferred or burned mid-lease?</li><li>[ ] If the arbiter never resolves a claim, what is the tenant&#39;s recourse?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Make the lease follow the deed: read <code>ownerOf</code> at claim time instead of storing the landlord. Then work out how a landlord could abuse that by selling the deed to themselves at the right moment.</li><li>Add a rent schedule with due dates and an arrears flag, and then argue about whether a contract should be able to brand someone a bad tenant permanently.</li><li>Escrow a photograph hash with each claim, so the evidence is at least timestamped. Note carefully what that does and does not prove.</li><li>Replace the single arbiter with the module 11 multisig, and measure how much slower the dispute path becomes.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.openzeppelin.com/contracts/5.x/api/token/erc20#SafeERC20" target="_blank" rel="noreferrer">OpenZeppelin SafeERC20</a></li><li><a href="https://docs.soliditylang.org/en/latest/security-considerations.html#use-the-checks-effects-interactions-pattern" target="_blank" rel="noreferrer">Checks-Effects-Interactions</a></li><li>Read how a statutory tenancy deposit scheme in your own country handles disputes, and list what it does that this contract cannot.</li></ul><p><strong>Next:</strong> <a href="./11-multisig-treasury">Module 11 · Multisig treasury →</a></p>`,52)])])}const m=t(i,[["render",o]]);export{u as __pageData,m as default};
